const payableStatementOpening = `-- name: PayableStatementOpening :one
SELECT (COALESCE((SELECT SUM(p.amount) FROM accounts_payable p
                  WHERE p.company_id = $1 AND p.supplier_id = $2 AND p.currency = $3::text
                    AND p.doc_date < $4::date), 0)
      - COALESCE((SELECT SUM(l.amount) FROM settlement_lines l JOIN settlements s ON s.id = l.settlement_id
                  WHERE s.company_id = $1 AND s.supplier_id = $2 AND s.currency = $3::text
                    AND s.status = 'posted' AND s.doc_date < $4::date), 0))::numeric AS opening
`

