const receivableAging = `-- name: ReceivableAging :many

WITH items AS (
    SELECT r.customer_id AS partner_id, ($3::date - r.due_date)::int AS days,
           (CASE WHEN r.amount = 0 THEN 0 ELSE r.base_amount * (r.amount - r.paid_amount) / r.amount END)::numeric AS bal
    FROM accounts_receivable r
    WHERE r.company_id = $4 AND r.amount <> r.paid_amount AND r.doc_date <= $3::date
)
SELECT c.id AS partner_id, c.code AS partner_code, c.name AS partner_name,
       COALESCE(SUM(i.bal) FILTER (WHERE i.days <= 0), 0)::numeric AS not_due,
       COALESCE(SUM(i.bal) FILTER (WHERE i.days BETWEEN 1 AND 30), 0)::numeric AS d1_30,
       COALESCE(SUM(i.bal) FILTER (WHERE i.days BETWEEN 31 AND 60), 0)::numeric AS d31_60,
       COALESCE(SUM(i.bal) FILTER (WHERE i.days BETWEEN 61 AND 90), 0)::numeric AS d61_90,
       COALESCE(SUM(i.bal) FILTER (WHERE i.days > 90), 0)::numeric AS d90_plus,
       COALESCE(SUM(i.bal), 0)::numeric AS total
FROM items i
JOIN customers c ON c.id = i.partner_id
LEFT JOIN users su ON su.id = c.sales_user_id
WHERE ($1::bigint IS NULL OR c.sales_user_id = $1)
  AND ($2::bigint IS NULL OR su.department_id = $2)
GROUP BY c.id
ORDER BY c.code
`

type ReceivableAgingParams struct {
	ScopeUserID *int64
	ScopeDeptID *int64
	AsOf        time.Time
	CompanyID   int64
}

type ReceivableAgingRow struct {
	PartnerID   int64
	PartnerCode string
	PartnerName string
	NotDue      decimal.Decimal
	D130        decimal.Decimal
	D3160       decimal.Decimal
	D6190       decimal.Decimal
	D90Plus     decimal.Decimal
	Total       decimal.Decimal
}

// ======== 帳齡分析 ========
// 以目前未沖餘額(本位幣,依原幣餘額比例換算)按到期日分組;as_of 之後的單據不計
func (q *Queries) ReceivableAging(ctx context.Context, arg ReceivableAgingParams) ([]ReceivableAgingRow, error) {
	rows, err := q.db.Query(ctx, receivableAging,
		arg.ScopeUserID,
		arg.ScopeDeptID,
		arg.AsOf,
		arg.CompanyID,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ReceivableAgingRow{}
	for rows.Next() {
		var i ReceivableAgingRow
		if err := rows.Scan(
			&i.PartnerID,
			&i.PartnerCode,
			&i.PartnerName,
			&i.NotDue,
			&i.D130,
			&i.D3160,
			&i.D6190,
			&i.D90Plus,
			&i.Total,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

