const setSettlementStatus = `-- name: SetSettlementStatus :one
UPDATE settlements
SET status       = $1,
    submitted_by = CASE WHEN $2::text = 'submit' THEN $3::bigint ELSE submitted_by END,
    submitted_at = CASE WHEN $2::text = 'submit' THEN now() ELSE submitted_at END,
    approved_by  = CASE WHEN $2::text = 'approve' THEN $3::bigint
                        WHEN $2::text IN ('reject', 'unapprove') THEN NULL ELSE approved_by END,
    approved_at  = CASE WHEN $2::text = 'approve' THEN now()
                        WHEN $2::text IN ('reject', 'unapprove') THEN NULL ELSE approved_at END,
    posted_by    = CASE WHEN $2::text = 'post' THEN $3::bigint
                        WHEN $2::text = 'unpost' THEN NULL ELSE posted_by END,
    posted_at    = CASE WHEN $2::text = 'post' THEN now()
                        WHEN $2::text = 'unpost' THEN NULL ELSE posted_at END,
    version      = version + 1,
    updated_by   = $3::bigint
WHERE id = $4 AND company_id = $5 AND version = $6
RETURNING id, company_id, side, doc_no, doc_date, customer_id, supplier_id, sales_user_id, currency, method, reference, amount, status, note, submitted_by, submitted_at, approved_by, approved_at, posted_by, posted_at, created_by, updated_by, version, created_at, updated_at
`

